<?php
/* Template Name: Instructor Admin Chat */
if ( ! sslms_is_chat_instructor() && ! sslms_is_chat_admin() ) {
  get_header();
    echo '<section class="lms-page"><div class="survey-permission"><strong>Chat access required.</strong><br>This page is available to instructors and administrators.</div></section>';
    get_footer(); return;
}
$is_admin = sslms_is_chat_admin();
$is_instructor = sslms_is_chat_instructor();
$chat_mode = sanitize_key( $_POST['chat_mode'] ?? $_GET['chat_mode'] ?? ( $is_admin ? 'instructors' : 'students' ) );
if ( $is_instructor && ! in_array( $chat_mode, array( 'students', 'administrators' ), true ) ) { $chat_mode = 'students'; }
$people = $is_admin ? get_users( array( 'role' => 'instructor', 'orderby' => 'display_name', 'order' => 'ASC' ) ) : ( 'administrators' === $chat_mode ? get_users( array( 'role' => 'administrator', 'orderby' => 'display_name', 'order' => 'ASC' ) ) : sslms_get_chat_students_for_instructor() );
$selected_id = absint( $_POST['chat_recipient_id'] ?? $_GET['chat_recipient_id'] ?? 0 );
if ( ! $selected_id && $people ) { $selected_id = $people[0]->ID; }
$selected = $selected_id ? get_userdata( $selected_id ) : false;
$chat_type = $is_instructor && 'students' === $chat_mode ? 'student_instructor' : 'instructor_admin';
$type_valid = $selected && ( $is_admin ? sslms_is_chat_instructor( $selected->ID ) : ( $is_instructor ? ( 'students' === $chat_mode ? sslms_is_student_user( $selected->ID ) : sslms_is_chat_admin( $selected->ID ) ) : sslms_is_chat_admin( $selected->ID ) ) );
$status = $type_valid ? sslms_handle_chat_actions( $chat_type, $selected->ID, 'sslms_instructor_admin_chat', 'sslms_instructor_admin_chat_nonce' ) : '';
if ( ! $status ) { $status = $type_valid && isset( $_POST['sslms_instructor_admin_chat_nonce'] ) ? sslms_save_chat_message( $chat_type, $selected->ID, 'sslms_instructor_admin_chat', 'sslms_instructor_admin_chat_nonce' ) : ''; }
if ( $status ) {
  wp_safe_redirect( add_query_arg( array( 'chat_recipient_id' => $selected_id, 'chat_mode' => $chat_mode, 'sslms_status' => $status ), get_permalink() ) );
  exit;
}
$status = sanitize_key( $_GET['sslms_status'] ?? '' );
$messages = $type_valid ? sslms_get_chat_messages( $chat_type, get_current_user_id(), $selected->ID ) : array();
get_header();
?>
<section class="lms-page chat-page">
  <div class="lms-toolbar"><div><p class="lms-kicker">Chat</p><h1 class="lms-section-title">Chat</h1><p><?php echo $is_instructor ? 'Read and reply to your conversations.' : 'Coordinate teaching, student support and important updates privately.'; ?></p></div><a class="lms-btn lms-btn--ghost" href="<?php echo esc_url( $is_admin ? home_url( '/' ) : sslms_instructor_profile_url() ); ?>"><?php echo $is_admin ? 'Back home' : 'Back to profile'; ?> <span aria-hidden="true">&#8594;</span></a></div>
  <?php if ( 'sent' === $status ) : ?><div class="profile-notice profile-notice--success">Your message has been sent.</div><?php elseif ( 'edited' === $status ) : ?><div class="profile-notice profile-notice--success">Your message has been updated.</div><?php elseif ( 'deleted' === $status ) : ?><div class="profile-notice profile-notice--success">Your message has been deleted.</div><?php elseif ( 'error' === $status ) : ?><div class="profile-notice profile-notice--error">We could not update that message. Please try again.</div><?php endif; ?>
  <?php if ( ! $people ) : ?><div class="lms-card chat-empty"><strong>No <?php echo $is_admin ? 'instructors' : ( $is_instructor && 'administrators' === $chat_mode ? 'administrators' : ( $is_instructor ? 'students have chosen you' : 'administrators' ) ); ?> yet.</strong><p>There is nobody to start a conversation with.</p></div>
  <?php else : ?><div class="chat-layout"><aside class="lms-card chat-contacts"><?php if ( $is_instructor ) : ?><form class="chat-mode-selector" method="get"><label><span>Chat</span><select name="chat_mode" onchange="this.form.submit()"><option value="students" <?php selected( $chat_mode, 'students' ); ?>>Students</option><option value="administrators" <?php selected( $chat_mode, 'administrators' ); ?>>Administrators</option></select></label></form><?php endif; ?><h2>Conversations</h2><?php foreach ( $people as $person ) : ?><a class="chat-contact<?php echo $selected && (int) $selected->ID === (int) $person->ID ? ' is-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'chat_recipient_id' => $person->ID, 'chat_mode' => $chat_mode ), get_permalink() ) ); ?>"><img src="<?php echo esc_url( sslms_student_profile_photo_url( $person->ID, 'thumbnail' ) ); ?>" alt=""><span><strong><?php echo esc_html( $person->display_name ); ?></strong><small><?php echo esc_html( $person->user_email ); ?></small></span></a><?php endforeach; ?></aside>
    <?php if ( $type_valid ) : ?><section class="lms-card chat-card"><div class="chat-card__header"><div><p class="lms-kicker">Private conversation</p><h2><?php echo esc_html( $selected->display_name ); ?></h2><small><?php echo esc_html( $is_admin ? 'Instructor' : ( $is_instructor ? ( 'students' === $chat_mode ? 'Student' : 'Administrator' ) : 'Administrator' ) ); ?></small></div><img src="<?php echo esc_url( sslms_student_profile_photo_url( $selected->ID, 'medium' ) ); ?>" alt=""></div><div class="chat-messages"><?php if ( $messages ) : foreach ( $messages as $message ) : $mine = (int) $message->post_author === get_current_user_id(); ?><article class="chat-message<?php echo $mine ? ' chat-message--mine' : ''; ?>"><div class="chat-message__body"><?php echo nl2br( esc_html( $message->post_content ) ); ?></div><small><?php echo esc_html( $mine ? 'You' : $selected->display_name ); ?> · <?php echo esc_html( get_the_date( 'M j, Y g:i a', $message ) ); ?></small><?php if ( $mine ) : ?><div class="chat-message__actions"><form method="post"><input type="hidden" name="chat_recipient_id" value="<?php echo esc_attr( $selected->ID ); ?>"><input type="hidden" name="chat_mode" value="<?php echo esc_attr( $chat_mode ); ?>"><input type="hidden" name="chat_message_id" value="<?php echo esc_attr( $message->ID ); ?>"><?php wp_nonce_field( 'sslms_instructor_admin_chat', 'sslms_instructor_admin_chat_nonce' ); ?><input type="hidden" name="sslms_chat_action" value="edit"><input class="chat-edit-input" type="text" name="chat_message" value="<?php echo esc_attr( $message->post_content ); ?>" required><button type="submit">Edit</button></form><form method="post"><input type="hidden" name="chat_recipient_id" value="<?php echo esc_attr( $selected->ID ); ?>"><input type="hidden" name="chat_mode" value="<?php echo esc_attr( $chat_mode ); ?>"><input type="hidden" name="chat_message_id" value="<?php echo esc_attr( $message->ID ); ?>"><?php wp_nonce_field( 'sslms_instructor_admin_chat', 'sslms_instructor_admin_chat_nonce' ); ?><input type="hidden" name="sslms_chat_action" value="delete"><button type="submit" onclick="return confirm('Delete this message?');">Delete</button></form></div><?php endif; ?></article><?php endforeach; else : ?><div class="chat-no-messages"><strong>Start the conversation</strong><p>Send your first message to <?php echo esc_html( $selected->display_name ); ?>.</p></div><?php endif; ?></div><form class="chat-form" method="post"><input type="hidden" name="chat_recipient_id" value="<?php echo esc_attr( $selected->ID ); ?>"><input type="hidden" name="chat_mode" value="<?php echo esc_attr( $chat_mode ); ?>"><?php wp_nonce_field( 'sslms_instructor_admin_chat', 'sslms_instructor_admin_chat_nonce' ); ?><label><span>Message</span><textarea name="chat_message" rows="3" placeholder="Write a message..." required></textarea></label><button class="lms-btn" type="submit">Send message <span aria-hidden="true">&#8594;</span></button></form></section><?php endif; ?></div><?php endif; ?>
</section>
<?php get_footer(); ?>
